30:func Extract(text string, keys []string) []string {
31:	if !utf8.ValidString(text) {
32:		return nil
33:	}
34:
35:	known := make([]string, 0, len(keys))
36:	registered := make(map[string]bool)
37:	for _, key := range keys {
38:		if validKey(key) && !registered[key] {
39:			known = append(known, key)
40:			registered[key] = true
41:		}
42:	}
43:	if len(known) == 0 {
44:		return nil
45:	}
46:
47:	var result []string
48:	seen := make(map[string]bool)
49:	var fence byte
50:	fenceWidth := 0
51:	for _, line := range strings.Split(text, "\n") {
52:		line = strings.TrimSuffix(line, "\r")
53:		// Quoted lines cannot change fence state, even inside a fence.
54:		if strings.HasPrefix(strings.TrimLeft(line, " \t"), ">") {
55:			continue
56:		}
57:		marker, width, tail := fenceRun(line)
58:		if fence != 0 {
59:			if marker == fence && width >= fenceWidth && strings.Trim(tail, " \t") == "" {
60:				fence = 0
61:			}
62:			continue
63:		}
64:		if width >= 3 {
65:			fence, fenceWidth = marker, width
66:			continue
67:		}
68:		result = extractLine(line, known, seen, result)
69:	}
70:	return result
71:}
