73:func validKey(key string) bool {
74:	if key == "" || !utf8.ValidString(key) {
75:		return false
76:	}
77:	for _, r := range key {
78:		if unicode.IsSpace(r) || unicode.IsControl(r) || r == '@' || r == '\\' || r == '`' {
79:			return false
80:		}
81:	}
82:	return true
83:}
