85:// fenceRun reads a possible fence after at most three ASCII spaces.
86:func fenceRun(line string) (marker byte, width int, tail string) {
87:	i := 0
88:	for i < len(line) && line[i] == ' ' {
89:		i++
90:	}
91:	if i > 3 || i == len(line) || (line[i] != '`' && line[i] != '~') {
92:		return 0, 0, ""
93:	}
94:	marker = line[i]
95:	j := i
96:	for j < len(line) && line[j] == marker {
97:		j++
98:	}
99:	return marker, j - i, line[j:]
100:}
