102:func extractLine(line string, keys []string, seen map[string]bool, result []string) []string {
103:	spanWidth := 0
104:	for i := 0; i < len(line); {
105:		if line[i] == '`' {
106:			j := i
107:			for j < len(line) && line[j] == '`' {
108:				j++
109:			}
110:			if spanWidth == 0 {
111:				spanWidth = j - i
112:			} else if j-i == spanWidth {
113:				spanWidth = 0
114:			}
115:			i = j
116:			continue
117:		}
118:		if spanWidth != 0 || line[i] != '@' || !mentionStart(line, i) {
119:			i++
120:			continue
121:		}
122:
123:		best := ""
124:		for _, key := range keys {
125:			if len(key) <= len(best) || !strings.HasPrefix(line[i+1:], key) {
126:				continue
127:			}
128:			end := i + 1 + len(key)
129:			if end < len(line) {
130:				r, _ := utf8.DecodeRuneInString(line[end:])
131:				if identifierRune(r) {
132:					continue
133:				}
134:			}
135:			best = key
136:		}
137:		if best == "" {
138:			i++
139:			continue
140:		}
141:		if !seen[best] {
142:			seen[best] = true
143:			result = append(result, best)
144:		}
145:		i += 1 + len(best)
146:	}
147:	return result
148:}
149:
150:func identifierRune(r rune) bool {
151:	return unicode.IsLetter(r) || unicode.IsNumber(r) || unicode.IsMark(r) || r == '_' || r == '-'
152:}
153:
154:func mentionStart(line string, at int) bool {
155:	// Escape parity is checked before the ordinary left boundary.
156:	slashes := 0
157:	for i := at - 1; i >= 0 && line[i] == '\\'; i-- {
158:		slashes++
159:	}
160:	if slashes%2 != 0 {
161:		return false
162:	}
163:	if at == 0 {
164:		return true
165:	}
166:	r, _ := utf8.DecodeLastRuneInString(line[:at])
167:	return !identifierRune(r) && r != '.' && r != '+' && r != '@'
168:}
