171:func Route(state State, author Author, text string, keys []string) []Delivery {
172:	var when string
173:	switch author {
174:	case Human:
175:		switch state {
176:		case Pending:
177:			when = "start"
178:		case Busy:
179:			when = "soon"
180:		case Finished:
181:			when = "new"
182:		default:
183:			return nil
184:		}
185:	case Agent:
186:		if state != Busy {
187:			return nil
188:		}
189:		when = "soon"
190:	default:
191:		return nil
192:	}
193:
194:	mentions := Extract(text, keys)
195:	var deliveries []Delivery
196:	for _, key := range mentions {
197:		deliveries = append(deliveries, Delivery{Key: key, When: when})
198:	}
199:	return deliveries
